<?php
require_once 'functions.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT p.*,k.nama_kategori FROM tbl_produk p JOIN tbl_kategori k ON k.id_kategori=p.id_kategori WHERE p.id_produk=? AND p.status='aktif'");$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Produk tidak ditemukan');}
if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['pelanggan']);check_csrf();$qty=max(1,(int)($_POST['jumlah']??1));if($p['jenis_produk']==='barang' && $qty>(int)$p['stok']){flash('Jumlah melebihi stok.','error');go('detail_produk.php?id='.$id);} $cart=active_cart($pdo,(int)user()['id_user']);$st=$pdo->prepare("SELECT id_detail_keranjang,jumlah FROM tbl_detail_keranjang WHERE id_keranjang=? AND id_produk=?");$st->execute([$cart,$id]);$old=$st->fetch();if($old){$new=(int)$old['jumlah']+$qty;$pdo->prepare("UPDATE tbl_detail_keranjang SET jumlah=?,harga=?,subtotal=? WHERE id_detail_keranjang=?")->execute([$new,$p['harga'],$new*$p['harga'],$old['id_detail_keranjang']]);}else{$pdo->prepare("INSERT INTO tbl_detail_keranjang(id_keranjang,id_produk,jumlah,harga,subtotal) VALUES(?,?,?,?,?)")->execute([$cart,$id,$qty,$p['harga'],$qty*$p['harga']]);}flash('Produk ditambahkan ke keranjang.');go('keranjang.php');}
layout_header($p['nama_produk']);
?>
<div class="detail-grid"><div class="detail-image"><img src="<?=e(product_image($p['foto']))?>" alt="<?=e($p['nama_produk'])?>"></div><div class="detail-copy"><span class="tag"><?=e($p['nama_kategori'])?></span><h1><?=e($p['nama_produk'])?></h1><p><?=nl2br(e($p['deskripsi']))?></p><div class="detail-price"><?=rupiah($p['harga'])?></div><p class="muted">Stok: <?=$p['stok']?> <?=e($p['satuan'])?> · <?=e($p['jenis_produk'])?></p><?php if(role()==='pelanggan'):?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><label>Jumlah</label><input type="number" name="jumlah" value="1" min="1" max="<?=max(1,(int)$p['stok'])?>"><button class="btn btn-primary">＋ Masukkan Keranjang</button></form><?php elseif(!user()):?><a class="btn btn-primary" href="login.php">Masuk untuk membeli</a><?php endif;?></div></div>
<?php layout_footer(); ?>
